import{_ as t,o,c as d,a2 as a}from"./chunks/framework.BM5YPQmL.js";const f=JSON.parse('{"title":"OCBL - the Open Cube OS boot loader: architecture and responsibilities","description":"","frontmatter":{},"headers":[],"relativePath":"components/ocbl/ocbl-architecture.md","filePath":"components/ocbl/ocbl-architecture.md"}'),r={name:"components/ocbl/ocbl-architecture.md"};function i(c,e,s,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="ocbl-the-open-cube-os-boot-loader-architecture-and-responsibilities" tabindex="-1">OCBL - the Open Cube OS boot loader: architecture and responsibilities <a class="header-anchor" href="#ocbl-the-open-cube-os-boot-loader-architecture-and-responsibilities" aria-label="Permalink to &quot;OCBL - the Open Cube OS boot loader: architecture and responsibilities&quot;">​</a></h1><p>OCBL is the native boot loader of Open Cube OS. It replaces GRUB on Open Cube OS media: the boot code <code>ocbl-install</code> writes, the recovery disk&#39;s stage1, and the ISO&#39;s boot image are all OCBL. It lives in <code>ocbl/</code> and builds in <strong>two firmware flavors</strong> from one shared core.</p><h2 id="one-core-two-firmware-flavors" tabindex="-1">One core, two firmware flavors <a class="header-anchor" href="#one-core-two-firmware-flavors" aria-label="Permalink to &quot;One core, two firmware flavors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flavor</th><th>Entry</th><th>Real-mode plumbing</th><th>Console</th><th>Disk</th><th>Video</th></tr></thead><tbody><tr><td>BIOS</td><td><code>bios/stage1.asm</code></td><td>16-bit trampolines (<code>tramp16.asm</code>), int13 DAP reads through a sub-1 MiB bounce window</td><td>VGA text + serial</td><td>int13</td><td>VBE (<code>ocbl_vbe.c</code>)</td></tr><tr><td>UEFI</td><td><code>efi/efi_entry.c</code></td><td>none - native 64-bit from the start</td><td>GOP console + serial</td><td>EFI BlockIo (<strong>drive numbering starts at zero</strong>)</td><td>GOP (<code>ocbl_gop_efi.c</code>)</td></tr></tbody></table><p>Both flavors compile the same <code>common/</code> core: the entry scanner (<code>ocbl_scan.c</code>), the menu (<code>ocbl_menu.c</code>), the filesystems (<code>ocbl_fs.c</code>), the partition decoder (<code>ocbl_part.c</code>), the ELF loader (<code>ocbl_load.c</code>), the boot-state monitor (<code>ocbl_statemon.c</code>) and the watchdog driver (<code>ocbl_wdt.c</code>).</p><h2 id="the-handoff-contract" tabindex="-1">The handoff contract <a class="header-anchor" href="#the-handoff-contract" aria-label="Permalink to &quot;The handoff contract&quot;">​</a></h2><p>OCBL loads the kernel and hands off exactly like GRUB does - 32-bit protected mode, paging off, <code>EAX = 0x36D76289</code> (the multiboot2 magic), <code>EBX</code> = the MBI physical address, jump to the kernel&#39;s 32-bit entry. The fixed physical layout of a BIOS-flavor load:</p><table tabindex="0"><thead><tr><th>Address</th><th>Contents</th></tr></thead><tbody><tr><td><code>0x30000</code>-<code>0x3FFFF</code></td><td>64 KiB read bounce window (int13 DAP must target &lt;1 MiB)</td></tr><tr><td><code>0x50000</code></td><td>multiboot2 info (64 KiB)</td></tr><tr><td><code>0x400000+</code></td><td>kernel PT_LOAD segments (kernel link base)</td></tr><tr><td><code>0x800000+</code></td><td>the mb2 &quot;self&quot; module copy of the kernel ELF</td></tr><tr><td><code>0x1000000+</code></td><td>the OCIRE payload (menu entry OCBL_ENT_OCIRE)</td></tr></tbody></table><p>The UEFI flavor keeps the same MBI contract but exits boot services instead of downgrading to real mode.</p><h2 id="what-ocbl-scans-for" tabindex="-1">What OCBL scans for <a class="header-anchor" href="#what-ocbl-scans-for" aria-label="Permalink to &quot;What OCBL scans for&quot;">​</a></h2><p>The scanner walks every BIOS drive plus the boot CD, decodes the partition tables, mounts the filesystems it knows and produces the entry table the menu renders. Seven entry classes:</p><table tabindex="0"><thead><tr><th>Class</th><th>Detected by</th></tr></thead><tbody><tr><td>OCOS</td><td>any volume with <code>/boot/opencube.elf</code> carrying the multiboot2 magic; the A/B flag protocol picks the slot</td></tr><tr><td>OCIRE</td><td>the 0xEE shadow volume (or any volume) with <code>/boot/ocire.elf</code>; on the WP-07 recovery disk, the two independent slot partitions</td></tr><tr><td>OCSE</td><td>an ISO9660 volume carrying <code>/ocse.marker</code> (the install-media contract)</td></tr><tr><td>WINDOWS</td><td>a volume with <code>/EFI/Microsoft/Boot/bootmgfw.efi</code></td></tr><tr><td>LINUX</td><td>an ESP with a foreign EFI loader (<code>grubx64.efi</code> / <code>shimx64.efi</code> / <code>systemd-bootx64.efi</code> under <code>/EFI/&lt;vendor&gt;/</code>) - the vendor dir names the entry</td></tr><tr><td>GENERIC</td><td>an ESP with <code>/EFI/BOOT/BOOTX64.EFI</code> matching none of the above</td></tr><tr><td>SHUTDOWN</td><td>synthesized, always last</td></tr></tbody></table><p>Declared limit: 3.0.0 ships no ext2/3/4 driver in OCBL, so Linux systems are detected through their ESP loaders, never through <code>/boot</code> on an ext root; Windows likewise (NTFS is not parsed - detection is ESP-based, booting is chainload-based).</p><h2 id="responsibilities-beyond-loading" tabindex="-1">Responsibilities beyond loading <a class="header-anchor" href="#responsibilities-beyond-loading" aria-label="Permalink to &quot;Responsibilities beyond loading&quot;">​</a></h2><p>OCBL is also the <strong>first responder</strong> of the reliability chain:</p><ul><li>it arms the boot-phase watchdog budget before every monitored payload handoff (the i6300ESB relay),</li><li>it diagnoses the previous boot from the state areas after a reset,</li><li>it records boot failures, counts consecutive failures and routes the machine into OCIRE when the threshold is reached.</li></ul><p>Those mechanics are the subject of <a href="./ocbl-ab.html">dual-firmware boot and A/B slot decisions</a> and <a href="./ocbl-troubleshooting.html">troubleshooting and status codes</a>.</p>',17)])])}const m=t(r,[["render",i]]);export{f as __pageData,m as default};
